export interface CartChunks {
  body: string;
  footer: string;
  upsells: string;
}

const stripHideInMinicart = (html: string): string =>
  html.replace(/\s?hide-in-minicart/g, "");

const parseCartHtml = (cartHtml: string): CartChunks => {
  const doc = new DOMParser().parseFromString(cartHtml, "text/html");
  const body = doc.querySelector(".cart-form__table-body")?.innerHTML ?? "";
  const footer =
    doc.querySelector(".cart-form__summary-block")?.innerHTML ?? "";
  const upsellsRaw = doc.querySelector(".cart-form__upsells")?.innerHTML ?? "";
  const upsells = stripHideInMinicart(upsellsRaw);
  return { body, footer, upsells };
};

/**
 * Fetches cart HTML via Section Rendering API; if blocks (e.g., upsells) are
 * missing due to instance-id differences, falls back to scraping /cart.
 */
export async function fetchCartChunks(): Promise<CartChunks> {
  try {
    const res = await fetch("/?sections=cart");
    const sections = await res.json();
    const cartHtml = sections?.cart || "";

    const parsed = parseCartHtml(cartHtml);

    // Fallback if upsells (or core parts) are empty
    if (!parsed.upsells && (!parsed.body || !parsed.footer)) {
      const fullHtml = await fetch("/cart").then((r) => r.text());
      return parseCartHtml(fullHtml);
    }

    // Still fallback if only upsells empty
    if (!parsed.upsells) {
      const fullHtml = await fetch("/cart").then((r) => r.text());
      const fallback = parseCartHtml(fullHtml);
      return { ...parsed, upsells: fallback.upsells };
    }

    return parsed;
  } catch {
    // Last resort
    const fullHtml = await fetch("/cart").then((r) => r.text());
    return parseCartHtml(fullHtml);
  }
}
